/**
 * Members specific to the code, for example the fields that failed validation.
 */
export type ProblemDetails = { [key: string]: unknown };

/**
 * RFC 9457 problem with the Cadenway extensions `code` and `details`.
 */
export interface Problem {
  /** URI reference that identifies the problem type. */
  type: string;
  /** Short summary of the problem type, the same for every occurrence. */
  title: string;
  /** HTTP status of the response. */
  status: number;
  /** Explanation specific to this occurrence. */
  detail?: string;
  /** URI reference that identifies this occurrence. */
  instance?: string;
  /** Stable machine code, `<domain>.<reason>`. */
  code: string;
  /** Members specific to the code, for example the fields that failed validation. */
  details?: ProblemDetails;
}

/**
 * `request.invalid`: the request does not match the schema; one `details.issues` entry per issue.
 */
export type BadRequestResponse = Problem;

/**
 * The internal token is missing (`auth.token-missing`) or refused (`auth.token-invalid`, with
 * `details.reason`). The gateway's client reports it as `503 upstream.unauthorized`.
 */
export type InternalTokenRefusedResponse = Problem;

/**
 * The internal token is valid but the route does not accept its issuer
 * (`auth.issuer-not-allowed`) or its actor (`auth.actor-not-allowed`), or it carries no
 * organization (`auth.organization-required`).
 */
export type InternalAccessRefusedResponse = Problem;

/**
 * - `organization.role-forbidden`: a guest does not create spaces;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`, `auth.organization-required`: see
 *   the internal token.
 */
export type RoleForbiddenResponse = Problem;

/**
 * - `space.visibility-forbidden`: only the owner of the space, and the owner and the admins
 *   of the organization, change its visibility;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`, `auth.organization-required`: see
 *   the internal token.
 */
export type SpaceWriteForbiddenResponse = Problem;

/**
 * `organization.not-found`: task-service does not hold the actor as a member of the
 * organization of the token, removed or not yet learnt.
 */
export type OrganizationNotFoundResponse = Problem;

/**
 * - `user.not-found`: the `userId` of the path is not the actor;
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type UserNotFoundResponse = Problem;

/**
 * - `space.not-found`: no space with this id that the actor sees;
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type SpaceNotFoundResponse = Problem;

/**
 * - `list.not-found`: no list with this id that the actor sees;
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type ListNotFoundResponse = Problem;

/**
 * - `task.not-found`: no task with this key that the actor sees;
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type TaskNotFoundResponse = Problem;

/**
 * - `checklist-item.not-found`: the task has no item with this id;
 * - `task.not-found`, `organization.not-found`: see `TaskNotFound`.
 */
export type ChecklistItemNotFoundResponse = Problem;

/**
 * `space.prefix-taken`: another space of the organization uses or used the prefix, with `details.prefix`.
 */
export type PrefixTakenResponse = Problem;

/**
 * `space.prefix-taken`, with `details.prefix`, or `idempotency.request-in-progress`.
 */
export type SpaceCreationConflictResponse = Problem;

/**
 * `idempotency.request-in-progress`: a request with the same `Idempotency-Key` still runs.
 */
export type RequestInProgressResponse = Problem;

/**
 * `idempotency.key-reused`: the `Idempotency-Key` was sent before with another body.
 */
export type IdempotencyKeyReusedResponse = Problem;

/**
 * `space.status-required`: the patch hides `todo` or `done`, with `details.status`.
 */
export type StatusRequiredResponse = Problem;

/**
 * `list.sprint-dates-invalid` or `idempotency.key-reused`.
 */
export type ListCreationRefusedResponse = Problem;

/**
 * `list.sprint-dates-invalid`: the end of the sprint is before its start.
 */
export type SprintDatesInvalidResponse = Problem;

/**
 * A task rule refuses the request, with the codes of the public route: `task.status-hidden`
 * (`details.status`), `task.cancel-reason-required`, `task.cancel-reason-unexpected`,
 * `task.assignee-invalid` (`details.userIds`, at a creation), `task.start-date-invalid`,
 * `task.list-invalid`, `task.parent-invalid` (`details.parentKey`),
 * `task.subtask-depth-exceeded`, `task.subtask-limit-reached`, or, on a creation,
 * `idempotency.key-reused`.
 */
export type TaskRefusedResponse = Problem;

/**
 * `task.assignee-invalid`, with `details.userIds`, or `task.assignee-limit-reached` beyond 20 assignees.
 */
export type AssigneeRefusedResponse = Problem;

/**
 * `task.label-limit-reached`: the task has 20 labels.
 */
export type LabelLimitReachedResponse = Problem;

/**
 * `task.checklist-limit-reached` beyond 100 items, or `idempotency.key-reused`.
 */
export type ChecklistItemRefusedResponse = Problem;

/**
 * `request.version-mismatch`: `If-Match` is not the current version, with `details.version`.
 */
export type VersionMismatchResponse = Problem;

/**
 * `"<version>"` the change was made from.
 */
export type IfMatchParameter = string;

/**
 * Key of the creation, as the client sent it to the gateway.
 */
export type IdempotencyKeyParameter = string;

/**
 * The date of the caller, in their time zone, which task-service does not know: the late
 * tasks, the tasks due that day and the current sprints are counted against it.
 */
export type TodayParameter = string;

